import Component from "../kokonut/SpotlightCards";
import { Zap, Lock, Globe, Code } from "lucide-react";
import { DemoFrame } from "../shared/DemoFrame";

export default function Demo() {
  return (
    <DemoFrame className="h-[420px] p-0">
      <div className="w-full shrink-0 scale-[.68] flex justify-center">
        <Component
          items={[
            {
              icon: Zap,
              title: "Instant",
              description: "Small details. A satisfying response.",
              color: "#f59e0b",
            },
            {
              icon: Lock,
              title: "Thoughtful",
              description: "Keep the essentials close at hand.",
              color: "#60a5fa",
            },
            {
              icon: Globe,
              title: "Connected",
              description: "A shared space for your next idea.",
              color: "#34d399",
            },
            {
              icon: Code,
              title: "Made for you",
              description: "A little room to make it your own.",
              color: "#a78bfa",
            },
          ]}
        />
      </div>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

